func TestExpiredAssetCannotBeExportedAtRequestTime(t *testing.T){s:=memory.NewStore();ps:=NewProjectService(s,s,clock.System{},&ids.Sequence{});_,_=ps.Create(context.Background(),application.CreateProjectInput{ID:"p",Name:"P",OwnerID:"o"}); as:=NewAssetService(s,s,s,clock.System{},&ids.Sequence{}); exp:=time.Now().Add(-time.Hour).UTC().Format(time.RFC3339);_,e:=as.Create(context.Background(),application.CreateAssetInput{ID:"a",ProjectID:"p",Name:"x",Bytes:1,CopyrightNote:"licensed",ExpiresAt:&exp});if e!=nil{t.Fatal(e)};if _,e=as.Exportable(context.Background(),"a",time.Now().UTC());e==nil{t.Fatal("expired asset exported")}}
